-- Importação de 1237 perguntas do app offline
INSERT INTO duel_questions (question, options, correct_index, category, difficulty, verse_ref, is_active) VALUES 
('Quem viu descer do céu um vaso como se fosse um lençol cheio de animais?', '["João", "Lucas", "Pedro", "Paulo"]', 2, 'evangelhos', 'facil', 'E viu o céu aberto, e que descia um vaso, como se fosse um grande lençol atado pelas quatro pontas, e vindo para a terra. (Atos 10 : 11)', true),
('Quem viu Jesus pela 1ª vez após a sua morte?', '["Maria, sua mãe", "Maria de Betânia", "Maria Madalena", "O Jardineiro"]', 2, 'evangelhos', 'medio', 'Maria Madalena foi e anunciou aos discípulos que vira o Senhor, e que ele lhe dissera isto. (João 20 : 18)', true),
('Qual é o profeta que fala de meninos e de meninas brincando nas ruas?', '["Zacarias", "Davi", "Ezequiel", "Naum"]', 0, 'geral', 'facil', 'E as ruas da cidade se encherão de meninos e meninas, que nelas brincarão. (Zacarias 8 : 5)', true),
('Qual desses anjos é mencionado pelo nome no Novo Testamento?', '["Rafael", "Gamaliel", "Hilel", "Gabriel"]', 3, 'evangelhos', 'medio', 'E, respondendo o anjo, disse-lhe: Eu sou Gabriel, que assisto diante de Deus, e fui enviado a falar-te e dar-te estas alegres novas. (Lucas 1 : 19)', true),
('Segundo a Bíblia o que quer dizer (Rabôni)?', '["Sacerdote", "Mestre", "Pai", "Deus"]', 1, 'evangelhos', 'facil', 'Disse-lhe Jesus: Maria! Ela, voltando-se, disse-lhe: Raboni (que quer dizer, Mestre). (João 20 : 16)', true),
('Qual é o profeta que descreve o Éden como o jardim de Deus?', '["Ezequiel", "Oséias", "Joel", "Habacuque"]', 0, 'geral', 'medio', 'Estiveste no Éden, jardim de Deus; de toda a pedra preciosa era a tua cobertura: sardônia, topázio, diamante, turquesa, ônix, jaspe, safira, carbúnculo, esmeralda e ouro; em ti se faziam os teus tambores e os teus pífaros; no dia em que foste criado foram preparados. (Ezequiel 28 : 13)', true),
('Quem quase provocou o massacre de uma nação por se recusar a fazer saudação?', '["Davi", "Mardoqueu", "Naamã", "Ageu"]', 1, 'geral', 'facil', 'Vendo, pois, Hamã que Mardoqueu não se inclinava nem se prostrava diante dele, Hamã se encheu de furor. Est. 3:5,6', true),
('Qual foi o rei judeu que foi ferido de lepra?', '["Uzias", "Abraão", "Nabucodonozor", "Naamã"]', 0, 'geral', 'medio', 'Então Uzias se indignou; e tinha o incensário na sua mão para queimar incenso. Indignando-se ele, pois, contra os sacerdotes, a lepra lhe saiu à testa perante os sacerdotes, na casa do SENHOR, junto ao altar do incenso. (II Crônicas 26 : 19)', true),
('Das pessoas que saíram do Egito, quantas entraram na terra prometida?', '["Tres Pessoas", "Mil Pessoas", "2 Pessoas", "100 Pessoas"]', 2, 'geral', 'facil', 'Porque o SENHOR dissera deles que certamente morreriam no deserto; e nenhum deles ficou senão Calebe, filho de Jefoné, e Josué, filho de Num. (Números 26 : 65)', true),
('Qual o nome do homem que no caminho do gólgota puséram-lhe a cruz às costas?', '["Simá", "Simão", "João", "Judas"]', 1, 'evangelhos', 'medio', 'E quando o iam levando, tomaram um certo Simão, cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse após Jesus. Lucas 23.26', true),
('Quem construiu a arca do concerto?', '["Araão", "Moisés", "Bezaleel", "Tubal Caim"]', 2, 'geral', 'facil', 'Depois disse Moisés aos filhos de Israel: Eis que o SENHOR tem chamado por nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá.  (Êxodo 35 : 30). Fez também dois querubins de ouro; de obra batida os fez, nas duas extremidades do propiciatório. (Êxodo 37 : 07)', true),
('Quem pediu o corpo de Jesus após sua morte?', '["Pilatos", "Herodes", "Nicodemos", "José de Arimatéia"]', 3, 'evangelhos', 'medio', 'Chegou José de Arimatéia, senador honrado, que também esperava o reino de Deus, e ousadamente foi a Pilatos, e pediu o corpo de Jesus. (Marcos 15 : 43)', true),
('Qual o homem que interpretou o sonho de Faraó?', '["Josué", "Jó", "José", "Jonas"]', 2, 'geral', 'facil', 'E Faraó disse a José: Eu tive um sonho, e ninguém há que o interprete; mas de ti ouvi dizer que quando ouves um sonho o interpretas. (Gênesis 41 : 15)', true),
('Quantos discípulos Jesus convocou?', '["10 Discípulos", "11 Discípulos", "12 Discípulos", "9 Discípulos"]', 2, 'evangelhos', 'medio', 'E, CONVOCANDO os seus doze discípulos, deu-lhes virtude e poder sobre todos os demônios, para curarem enfermidades. Lucas 9:1', true),
('Quantas virgens éram prudentes?', '["10 Virgens", "7 Virgens", "9 Virgens", "5 Virgens"]', 3, 'evangelhos', 'facil', 'E cinco delas eram prudentes, e cinco loucas. (Mateus 25 : 2)', true),
('Quem fez um ferro de um machado flutuar?', '["Elias", "Moisés", "Elizeu", "Naamã"]', 2, 'geral', 'medio', 'E disse o homem de Deus: Onde caiu? E mostrando-lhe ele o lugar, cortou um pau, e o lançou ali, e fez flutuar o ferro. (II Reis 6 : 6)', true),
('Qual o profeta que interpretou o sonho de nabucodonozor?', '["Oséias", "Mesaque", "Habidinego", "Daniel"]', 3, 'geral', 'facil', 'Respondeu o rei, e disse a Daniel (cujo nome era Beltessazar): Podes tu fazer-me saber o sonho que tive e a sua interpretação? (Daniel 2 : 26)', true),
('Por quem Sansão foi traído?', '["Raquel", "Núbia", "Dalila", "Raabe"]', 2, 'geral', 'medio', 'Vendo, pois, Dalila que já lhe descobrira todo o seu coração, mandou chamar os príncipes dos filisteus, dizendo: Subi esta vez, porque agora me descobriu ele todo o seu coração. E os príncipes dos filisteus subiram a ter com ela, trazendo com eles o dinheiro. (Juízes 16 : 18)', true),
('Qual a idade de Noé quando o dilúvio veio sobre a terra?', '["500 Anos", "450 Anos", "700 Anos", "600 Anos"]', 3, 'geral', 'facil', 'E era Noé da idade de seiscentos anos, quando o dilúvio das águas veio sobre a terra. (Gênesis 7 : 6)', true),
('De qual País era o homem que no caminho do gólgota puséram-lhe a cruz às costas?', '["Cirene", "Rabá", "Mesopotâmia", "Egito"]', 0, 'evangelhos', 'medio', 'E quando o iam levando, tomaram um certo Simão, cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse após Jesus. Lucas 23.26', true),
('Quem era o personagem envolto em um lençol sobre o corpo nu no dia da prisão de Jesus?', '["Um Velho", "Um Jovem", "Uma Jovem", "Sua Mãe"]', 1, 'evangelhos', 'facil', 'E um certo jovem o seguia, envolto em um lençol sobre o corpo nu. E lançaram-lhe a mão. (Marcos 14 : 51)', true),
('Quanto tempo viveu Sara?', '["100 Anos", "101 Anos", "127 Anos", "135 Anos"]', 2, 'geral', 'medio', 'E FOI a vida de Sara cento e vinte e sete anos; estes foram os anos da vida de Sara. (Gênesis 23 : 1)', true),
('Quantos anjos apareceram a Abraão e a Sara dizendo-lhes que eles haveriam de ter um filho?', '["Três Anjos", "Dois Anjos", "Quatro Anjos", "Um Anjo"]', 0, 'geral', 'facil', 'DEPOIS apareceu-lhe o SENHOR nos carvalhais de Manre, estando ele assentado à porta da tenda, no calor do dia. E levantou os seus olhos, e olhou, e eis três homens em pé junto a ele. E vendo-os, correu da porta da tenda ao seu encontro e inclinou-se à terra, E disse: Meu Senhor, se agora tenho achado graça aos teus olhos, rogo-te que não passes de teu servo. Que se traga já um pouco de água, e lavai os vossos pés, e recostai-vos debaixo desta árvore; E trarei um bocado de pão, para que esforceis', true),
('Qual o nome do primeiro nome que seria dado a Benjamim?', '["Benoni", "Benoá", "Bonearges", "Barnabé"]', 0, 'geral', 'medio', 'E aconteceu que, saindo-se-lhe a alma (porque morreu), chamou-lhe Benoni; mas seu pai chamou-lhe Benjamim. (Gênesis 35 : 18)', true),
('Ana pediu a Deus um filho. Qual era o nome dele?', '["Samuel", "Samá", "Simei", "Simeão"]', 0, 'geral', 'facil', 'E sucedeu que, passado algum tempo, Ana concebeu, e deu à luz um filho, ao qual chamou Samuel; porque, dizia ela, o tenho pedido ao SENHOR. (I Samuel 1 : 20)', true),
('Quanto tempo esteve o dilúvio sobre a terra?', '["50 Dias", "40 Dias", "10 Dias", "100 Dias"]', 1, 'geral', 'medio', 'E houve chuva sobre a terra quarenta dias e quarenta noites. (Gênesis 7 : 12)', true),
('Qual o nome do avô de Davi?', '["Naum", "Jessé", "Saul", "Obede"]', 3, 'geral', 'facil', 'E Obede gerou a Jessé, e Jessé gerou a Davi. (Rute 4 : 22)', true),
('Qual o parentesco do homem que batizou Jesus?', '["Amigo", "Primo", "Irmão", "Cunhado"]', 1, 'evangelhos', 'medio', 'Alguns acreditam que eles eram primos de segundo grau. Essa crença se baseia numa tradução imprecisa de Lucas 1:36. Por exemplo, esse versículo, na versão Almeida (edição revista e corrigida), diz que Elisabete (Isabel), mãe de João, e Maria, mãe de Jesus, eram primas.', true),
('Por quanto José do Egito foi vendido?', '["10 Moedas", "15 Moedas", "20 Moedas", "50 Moedas"]', 2, 'geral', 'facil', 'Passando, pois, os mercadores midianitas, tiraram e alçaram a José da cova, e venderam José por vinte moedas de prata, aos ismaelitas, os quais levaram José ao Egito. (Gênesis 37 : 28)', true),
('Quem Batizou Jesus no Rio Nilo?', '["João Batista", "José do Egito", "Paulo", "Nehuma das Alternativas"]', 3, 'geral', 'medio', 'Nehuma das Alternativas. Jesus foi batizado no Rio Jordão, não no Nilo, que era e ainda é o Maior Rio do Continente', true),
('Quem tinha como servo pessoal um soldado devoto?', '["Cornélio", "Pedro", "João", "José de Arimatéia"]', 0, 'evangelhos', 'facil', 'E, retirando-se o anjo que lhe falava, chamou dois dos seus criados, e a um piedoso soldado dos que estavam ao seu serviço. (Atos 10 : 7)', true),
('Que povo foi recriminado pelo profeta Isaías por consultar astrólogos?', '["Babilônia", "Assiria", "Egito", "Moabe"]', 0, 'geral', 'medio', 'DESCE, e assenta-te no pó, ó virgem filha de Babilônia; assenta-te no chão; já não há trono, ó filha dos caldeus, porque nunca mais serás chamada a tenra nem a delicado. Deixa-te estar com os teus encantamentos, e com a multidão das tuas feitiçarias, em que trabalhaste desde a tua mocidade, a ver se podes tirar proveito, ou se porventura te podes fortalecer. Cansaste-te na multidão dos teus conselhos; levantem-se pois agora os agoureiros dos céus, os que contemplavam os astros, os prognosticador', true),
('Quem foi condenado à morte por fazer sua oração?', '["Oséias", "Daniel", "Samuel", "Eli"]', 1, 'geral', 'facil', 'Daniel, pois, quando soube que o edito estava assinado, entrou em sua casa (ora havia no seu quarto janelas abertas do lado de Jerusalém), e três vezes no dia se punha de joelhos, e orava, e dava graças diante do seu Deus, como também antes costumava fazer. (Daniel 6 : 10)', true),
('Qual deste, é o livro da Bíblia que tem apenas 1 capítulo ?', '["Mateus", "Judas", "Ester", "Amós"]', 1, 'evangelhos', 'medio', 'Resposta certa é Judas.', true),
('Qual o nome do Rio cujo às águas estão cheias de sangue, segundo profeta Isaías?', '["Pison", "Eufrates", "Dimom", "Querite"]', 2, 'geral', 'facil', 'Porquanto as águas de Dimom estão cheias de sangue, porque ainda acrescentarei mais a Dimom; leões contra aqueles que escaparem de Moabe e contra o restante da terra. (Isaías 15 : 9)', true),
('Em qual dos Salmos lemos a respeito do gelo?', '["200", "54", "147", "100"]', 2, 'geral', 'medio', 'O que lança o seu gelo em pedaços; quem pode resistir ao seu frio? (Salmos 147 : 17)', true),
('Qual é o profeta da Escritura que fala da Palestina como Terra Santa?', '["Isaías", "Naum", "Zacarias", "Malaquias"]', 2, 'geral', 'facil', 'Então o SENHOR herdará a Judá como sua porção na terra santa, e ainda escolherá a Jerusalém. (Zacarias 2 : 12)', true),
('Em um desses livros da Bíblia não encontramos a palavra Deus ?', '["Ester", "Rute", "Lamentações", "Ezequiel"]', 0, 'geral', 'medio', 'O Livro de Ester não se menciona a Palavra Deus', true),
('Nome do Rei dos Sidônios?', '["Lameque", "Etbaal", "Jubal", "Nabal"]', 1, 'geral', 'facil', 'E sucedeu que (como se fora pouco andar nos pecados de Jeroboão, filho de Nebate) ainda tomou por mulher a Jezabel, filha de Etbaal, rei dos sidônios; e foi e serviu a Baal, e o adorou. (I Reis 16 : 31)', true),
('Quem foi o primeiro bígamo citado na Bíblia e quais eram os nomes das esposas ?', '["Salomão", "Jacó", "Lameque", "Judá"]', 2, 'geral', 'medio', 'E tomou Lameque para si duas mulheres; o nome de uma era Ada, e o nome da outra, Zilá. (Gênesis 4 : 19)', true),
('Onde lemos na Bíblia de camelos se ajoelhando ?', '["Exôdo", "Genêses", "Levítico", "Números"]', 1, 'geral', 'facil', 'E fez ajoelhar os camelos fora da cidade, junto a um poço de água, pela tarde, ao tempo que as moças saíam a tirar água. (Gênesis 24 : 11)', true),
('Homem rude casado com uma mulher formosa e sábia?', '["Nabal", "Jubal", "Davi", "Jessé"]', 0, 'geral', 'medio', 'E era o nome deste homem Nabal, e o nome de sua mulher Abigail; e era a mulher de bom entendimento e formosa; porém o homem era duro, e maligno nas obras, e era da casa de Calebe. (I Samuel 25 : 3)', true),
('Qual o menor livro da Bíblia ?', '["Judas", "II João", "III João", "II Pedro"]', 1, 'evangelhos', 'facil', 'II João (possui somente 13 versículos).', true),
('Quem foi o pai dos que habitam em tendas e possuem gado ?', '["Tubal", "Nabal", "Jabal", "Baal"]', 2, 'geral', 'medio', 'E Ada deu à luz a Jabal; este foi o pai dos que habitam em tendas e têm gado. (Gênesis 4 : 20)', true),
('Quem foi o pai de todos os que tocam harpa, flauta e órgão ?', '["Jubal", "Nabal", "Davi", "Asafe"]', 0, 'geral', 'facil', 'E o nome do seu irmão era Jubal; este foi o pai de todos os que tocam harpa e órgão. (Gênesis 4 : 21)', true),
('Qual o maior capítulo da Bíblia ?', '["Salmos 119", "Mateus 1", "Genêses 5", "Apocalipse 20"]', 0, 'geral', 'medio', 'Salmo 119 (possui 176 versículos).', true),
('Quem era rei e sacerdote ao mesmo tempo ?', '["Davi", "Samuel", "Melquisede", "Salém"]', 2, 'geral', 'facil', 'E Melquisedeque, rei de Salém, trouxe pão e vinho; e era este sacerdote do Deus Altíssimo. (Gênesis 14 : 18)', true),
('Qual o maior livro da Bíblia ?', '["Isaías", "Levítico", "Salmos", "Mateus"]', 2, 'geral', 'medio', 'Com 150 Números (Capítulos), o Livro de Salmos', true),
('Qual desses livros da Bíblia que terminam com um ponto de interrogação ?', '["Isaías", "Mateus", "Lamentações", "Genêses"]', 2, 'geral', 'facil', 'Converte-nos a ti, SENHOR, e seremos convertidos; renova os nossos dias como dantes. Mas tu nos rejeitaste totalmente. Tu estás muito enfurecido contra nós? Lamentações 5: 21-22', true),
('Qual o rei citado na Bíblia pelo seu peso ?', '["Eli", "Eglom", "Bem-Hadade", "Quiz"]', 1, 'geral', 'medio', 'E levou aquele presente a Eglom, rei dos moabitas; e era Eglom homem muito gordo. (Juízes 3 : 17)', true),
('Qual era a profissão de Neemias no palácio?', '["Padeiro", "Copeiro", "Músico", "Construtor"]', 1, 'geral', 'facil', 'Ah! Senhor, estejam, pois, atentos os teus ouvidos à oração do teu servo, e à oração dos teus servos que desejam temer o teu nome; e faze prosperar hoje o teu servo, e dá-lhe graça perante este homem. Então era eu copeiro do rei. (Neemias 1 : 11)', true),
('Qual o juiz de Israel que libertou o seu povo, usando como armas, tochas e trombetas?', '["Gideão", "Sansão", "Sangar", "Débora"]', 0, 'geral', 'medio', 'Assim tocaram as três companhias as buzinas, e quebraram os cântaros; e tinham nas suas mãos esquerdas as tochas acesas, e nas suas mãos direitas as buzinas, para tocarem, e clamaram: Espada do SENHOR, e de Gideão. (Juízes 7 : 20)', true),
('Reconstruí os muros de Jerusalém em 52 dias. Quem sou eu?', '["Zaquel", "Zorobabel", "Neemias", "Artaxerxes"]', 2, 'geral', 'facil', 'Acabou-se, pois, o muro aos vinte e cinco do mês de Elul; em cinqüenta e dois dias. (Neemias 6 : 15)', true),
('Qual o nome da única Juiza de Israel?', '["Débora", "Raabe", "Rute", "Ester"]', 0, 'geral', 'medio', 'E Débora, mulher profetisa, mulher de Lapidote, julgava a Israel naquele tempo. (Juízes 4 : 4)', true),
('Qual o homem que, depois de morto, matou mais pessoas que em sua vida ?', '["Jair", "Salomão", "Sansão", "Elizeu"]', 2, 'geral', 'facil', 'E disse Sansão: Morra eu com os filisteus. E inclinou-se com força, e a casa caiu sobre os príncipes e sobre todo o povo que nela havia; e foram mais os mortos que matou na sua morte do que os que matara em sua vida. (Juízes 16 : 30)', true),
('Qual o nome do profeta que exortou os filhos de Jerusalém a voltarem a pratica do dizímo?', '["Ezequiel", "Daniel", "Malaquias", "Ageu"]', 2, 'geral', 'medio', 'Trazei todos os dízimos à casa do tesouro, para que haja mantimento na minha casa, e depois fazei prova de mim nisto, diz o SENHOR dos Exércitos, se eu não vos abrir as janelas do céu, e não derramar sobre vós uma bênção tal até que não haja lugar suficiente para a recolherdes. (Malaquias 3 : 10)', true),
('Qual dos profetas teve seus pés postos num cepo?', '["Isaías", "Jeremias", "Jonas", "Miquéias"]', 1, 'geral', 'facil', 'E feriu Pasur ao profeta Jeremias, e o colocou no cepo que está na porta superior de Benjamim, na casa do SENHOR. (Jeremias 20 : 2)', true),
('Qual foi o homem no velho testamento que teve três ministérios?', '["Davi", "Melquisedeque", "Abraão", "Samuel"]', 3, 'geral', 'medio', 'Samuel foi profeta, sacerdote e juiz.', true),
('Qual o juiz de Israel que libertou o seu povo, usando um ferrão de tocar bois ?', '["Sansão", "Baraque", "Sangar", "Gideão"]', 2, 'geral', 'facil', 'Depois dele foi Sangar, filho de Anate, que feriu a seiscentos homens dos filisteus com uma aguilhada de bois; e também ele libertou a Israel. (Juízes 3 : 31)', true),
('Quem foram os três homens mais fiéis da Bíblia?', '["Davi, Salomão e Elias", "Elias, Elizeu e Jeremias", "Daniel, Samuel e Jó", "Noé, Daniel e Jó"]', 3, 'geral', 'medio', 'Noé, Daniel e Jó. Ainda que Noé, Daniel e Jó estivessem no meio dela, vivo eu, diz o Senhor DEUS, que nem um filho nem uma filha eles livrariam, mas somente eles livrariam as suas próprias almas pela sua justiça. (Ezequiel 14 : 20)', true),
('Qual o nome da árvore que Zaquel subiu pra ver Jesus?', '["Figueira", "Videira", "Carvalho", "Sicomôro"]', 3, 'evangelhos', 'facil', 'E, correndo adiante, subiu a um sicômoro para o ver; porque havia de passar por ali. (Lucas 19 : 4)', true),
('Qual era o nome da bisavó de Davi ?', '["Raabe", "Raquel", "Ester", "Rute"]', 3, 'geral', 'medio', 'E Salmom gerou, de Raabe, a Boaz; e Boaz gerou de Rute a Obede; e Obede gerou a Jessé; (Mateus 1 : 5). Jessé era Pai de Davi, portanto Rute, sua Bisavó.', true),
('Qual o comandante de Israel que disse que só iria à batalha se uma mulher fosse com ele ?', '["Jefte", "Baraque", "Bartimeu", "Jair"]', 1, 'geral', 'facil', 'Então lhe disse Baraque: Se fores comigo, irei; porém, se não fores comigo, não irei. (Juízes 4 : 8)', true),
('Qual o juiz de Israel tinha 30 filhos, que cavalgavam 30 jumentas e tinham 30 cidades ?', '["Sangar", "Jair", "Jefte", "Sansão"]', 1, 'geral', 'medio', 'E tinha este trinta filhos, que cavalgavam sobre trinta jumentos; e tinham trinta cidades, a que chamaram Havote-Jair, até ao dia de hoje; as quais estão na terra de Gileade. (Juízes 10 : 4)', true),
('Qual é o rei que foi denominado “Querubim Ungido”?', '["Rei do Egito", "Rei de Tiro", "Rei da Assíria", "Rei de Jerusalém"]', 1, 'geral', 'facil', 'Ez. 28:12-14', true),
('Urias, homem que Davi mandou matar, era o legítimo esposo de:', '["Bate-Seba", "Raabe", "Abigail", "Mical"]', 0, 'geral', 'medio', 'E mandou Davi indagar quem era aquela mulher; e disseram: Porventura não é esta Bate-Seba, filha de Eliã, mulher de Urias, o heteu? (II Samuel 11 : 3)', true),
('Qual o nome do filho de uma mãe que aguardava ansiosamente olhando pela janela ?', '["Sísera", "Baruque", "Balaque", "Balaão"]', 0, 'geral', 'facil', 'A mãe de Sísera olhava pela janela, e exclamava pela grade: Por que tarda em vir o seu carro? Por que se demoram os ruídos dos seus carros? (Juízes 5 : 28)', true),
('Qual o nome da mulher cujo rei estendeu à ela o cetro de ouro?', '["Rute", "Ester", "Raquel", "Jezabel"]', 1, 'geral', 'medio', 'E sucedeu que, vendo o rei à rainha Ester, que estava no pátio, alcançou graça aos seus olhos; e o rei estendeu para Ester o cetro de ouro, que tinha na sua mão, e Ester chegou, e tocou a ponta do cetro. (Ester 5 : 2)', true),
('Nome da Cidade onde Jonas fugiu a príncipio da ordem de Deus?', '["Nínive", "Troade", "Esparta", "Társis"]', 3, 'geral', 'facil', 'E orou ao SENHOR, e disse: Ah! SENHOR! Não foi esta minha palavra, estando ainda na minha terra? Por isso é que me preveni, fugindo para Társis, pois sabia que és Deus compassivo e misericordioso, longânimo e grande em benignidade, e que te arrependes do mal. (Jonas 4 : 2)', true),
('Qual a mulher que acolheu o seu inimigo e depois o matou ?', '["Jael", "Abigail", "Rebeca", "Jezabel"]', 0, 'geral', 'medio', 'Então Jael, mulher de Héber, tomou uma estaca da tenda, e lançou mão de um martelo, e chegou-se mansamente a ele, e lhe cravou a estaca na fonte, de sorte que penetrou na terra, estando ele, porém, num profundo sono, e já muito cansado; e assim morreu. (Juízes 4 : 21)', true),
('De onde foi tirada a madeira para a construção do 1º Templo de Jerusalém ?', '["Líbano", "Nigéria", "Espanha", "Roma"]', 0, 'geral', 'facil', 'Dá ordem, pois, agora, que do Líbano me cortem cedros, e os meus servos estarão com os teus servos, e eu te darei o salário dos teus servos, conforme a tudo o que disseres; porque bem sabes tu que entre nós ninguém há que saiba cortar a madeira como os sidônios. (I Reis 5 : 6)', true),
('Nome da mulher de Moisés que o chamou de sanguinário?', '["Zinia", "Zípora", "Siséra", "Priscíla"]', 1, 'geral', 'medio', 'Então Zípora tomou uma pedra aguda, e circuncidou o prepúcio de seu filho, e lançou-o a seus pés, e disse: Certamente me és um esposo sanguinário. (Êxodo 4 : 25)', true),
('Quantos cânticos Salomão compôs ?', '["Mil", "Mil e Trezentos", "Mil e Cinco", "Mil e Cem"]', 2, 'geral', 'facil', 'E disse três mil provérbios, e foram os seus cânticos mil e cinco. (I Reis 4 : 32)', true),
('Qual o nome da Cidade onde ficava o cego Bartimeu que foi curado por Jesus?', '["Jerusalém", "Samaria", "Siquém", "Jericó"]', 3, 'geral', 'medio', 'Depois, foram para Jericó. E, saindo ele de Jericó com seus discípulos e uma grande multidão, Bartimeu, o cego, filho de Timeu, estava assentado junto do caminho, mendigando. (Marcos 10 : 46)', true),
('Quem era Ailude no reino de Davi?', '["Copeiro", "Padeiro", "Cronista", "Guerreiro"]', 2, 'geral', 'facil', 'E Joabe, filho de Zeruia, era sobre o exército; e Jeosafá, filho de Ailude, era cronista. (II Samuel 8 : 16)', true),
('Quantos provérbios Salomão compôs ?', '["Três Mil e Cem", "Dois Mil", "Mil e cinco", "Três Mil"]', 3, 'geral', 'medio', 'E disse três mil provérbios, e foram os seus cânticos mil e cinco. (I Reis 4 : 32)', true),
('Que nome de criança comemorou a perda da glória de Israel?', '["Benoni", "Icabodê", "Benjamim", "Jefoné"]', 1, 'geral', 'facil', 'E chamou ao menino Icabode, dizendo: De Israel se foi a glória! Porque a arca de Deus foi tomada, e por causa de seu sogro e de seu marido. (I Samuel 4 : 21)', true),
('Que homem, citado na Bíblia, era o mais alto no meio do seu povo (que era formado por gigantes) ?', '["Anaque", "Azenate", "Arba", "Golias"]', 2, 'geral', 'medio', 'E antes o nome de Hebrom era Quiriate-Arba, porque Arba foi o maior homem entre os anaquins. E a terra repousou da guerra. (Josué 14 : 15)', true),
('Qual o nome da mulher dada a José por esposa no Egito?', '["Azenate", "Raabe", "Rebeca", "Ester"]', 0, 'geral', 'facil', 'E nasceram a José dois filhos (antes que viesse um ano de fome), que lhe deu Azenate, filha de Potífera, sacerdote de Om. (Gênesis 41 : 50)', true),
('Em qual país, por algum tempo, era impossível encontrar-se um ferreiro?', '["Israel", "Filístia", "Assíria", "Síria"]', 0, 'geral', 'medio', 'E em toda a terra de Israel nem um ferreiro se achava, porque os filisteus tinham dito: Para que os hebreus não façam espada nem lança. (I Samuel 13 : 19)', true),
('Quem foi o 1º homem, citado na Bíblia, que se enforcou ?', '["Ananias", "Padeiro-mor", "Aitofel", "Ismael"]', 2, 'geral', 'facil', 'Vendo, pois, Aitofel que se não tinha seguido o seu conselho, albardou o jumento, e levantou-se, e foi para sua casa e para a sua cidade, e deu ordem à sua casa, e se enforcou e morreu, e foi sepultado na sepultura de seu pai. (II Samuel 17 : 23)', true),
('De quem era filho o homem cujo o nome é o mais comprido e estranho de toda a bíblia, Maersalalhasbas?', '["Jeremias", "Isaías", "Malaquias", "Zaquel"]', 1, 'geral', 'medio', 'E fui ter com a profetiza, e ela concebeu, e deu à luz um filho; e o SENHOR me disse: Põe-lhe o nome de Maer-Salal-Has-Baz.  (Isaías 8 : 3)', true),
('Nome do pai de uma família que muitas vezes socorreu Paulo?', '["Alexandre", "Tito", "Onesiforo", "Parmênedes"]', 2, 'evangelhos', 'facil', 'O SENHOR conceda misericórdia à casa de Onesíforo, porque muitas vezes me recreou, e não se envergonhou das minhas cadeias. (II Timóteo 1 : 16)', true),
('A mãe de quem que recebeu um salário para criar o seu próprio filho ?', '["Josué", "Noé", "Jacó", "Moisés"]', 3, 'geral', 'medio', 'Então lhe disse a filha de Faraó: Leva este menino, e cria-mo; eu te darei teu salário. E a mulher tomou o menino, e criou-o. (Êxodo 2 : 9)', true),
('Tamar era o que de Judá?', '["Sogra", "Irmã", "Nora", "Mulher"]', 2, 'geral', 'facil', 'Judá, pois, tomou uma mulher para Er, o seu primogênito, e o seu nome era Tamar. (Gênesis 38 : 6)', true),
('Que homem israelita era celebrado por sua beleza ?', '["Salomão", "Absalão", "Samá", "Saul"]', 1, 'geral', 'medio', 'Não havia, porém, em todo o Israel homem tão belo e tão aprazível como Absalão; desde a planta do pé até à cabeça não havia nele defeito algum. (II Samuel 14 : 25)', true),
('Que Apóstolo foi morto por Herodes?', '["Paulo", "Tiago", "Pedro", "Jonas"]', 1, 'evangelhos', 'facil', 'Atos 12 1-2 Por aquele mesmo tempo o rei Herodes estendeu as mãos sobre alguns da igreja, para os maltratar; 2 E matou à espada Tiago, irmão de João.', true),
('Que latoeiro se opôs a Paulo?', '["Imineu", "Filêto", "Alexandre", "Andrônico"]', 2, 'evangelhos', 'medio', 'Alexandre, o latoeiro, causou-me muitos males; o Senhor lhe pague segundo as suas obras. (II Timóteo 4 : 14)', true),
('Qual foi o jovem que sofreu por adormecer durante um longo sermão?', '["Imineu", "Timóteo", "Tito", "Êutico"]', 3, 'evangelhos', 'facil', 'E, estando um certo jovem, por nome Êutico, assentado numa janela, caiu do terceiro andar, tomado de um sono profundo que lhe sobreveio durante o extenso discurso de Paulo; e foi levantado morto. (Atos 20 : 9)', true),
('Qual o nome do sogro de Judá?', '["Sua", "Emeleque", "Er", "Selá"]', 0, 'geral', 'medio', 'E viu Judá ali a filha de um homem cananeu, cujo nome era Sua; e tomou-a por mulher, e a possuiu. (Gênesis 38 : 2)', true),
